for(const f of flowers){if(Math.abs(f.x-750)<35||Math.abs(f.x-350)<38)continue;path([[f.x,f.y],[f.x-2,f.y-5-f.s*4]],'#8faa61',1.4);if(f.s>.55){ell(f.x-2,f.y-8,3,3,f.c);ell(f.x-2,f.y-8,1.2,1.2,'#c3a45d');}}
