function drawScorches(){for(const m of (worldState?.scorches||[]).slice(0,24)){ctx.save();const r=m.radius||16,c=Math.cos(m.heading),sn=Math.sin(m.heading);for(let j=0;j<4;j++){ctx.globalAlpha=[.08,.12,.18,.3][j]*Math.min(1,m.life/3);path([[m.x+c*r,m.y+sn*r],[m.x+c*(m.length-r),m.y+sn*(m.length-r)]],'#393124',r*2*(1.18-j*.15));}ctx.restore();}}
